public protocol IAlphaSynthAudioExporter: AnyObject {
    /**
     * Renders the next chunk of audio and provides it as result.
     */
    func render(_ milliseconds: Double) throws -> AudioExportChunk?
}

/**
 * A audio exporter allowing streaming synthesis of audio samples with a fixed configuration.
 */
public final class AlphaSynthAudioExporter: IAlphaSynthAudioExporter {
    private var _synth: TinySoundFont!

    private var _sequencer: MidiFileSequencer!

    public init(_ options: AudioExportOptions) {
        self._synth = TinySoundFont(options.sampleRate)
        self._sequencer = MidiFileSequencer(self._synth)
        self._synth.masterVolume = Math.max(options.masterVolume, SynthConstants.MinVolume)
        self._synth.metronomeVolume = Math.max(options.metronomeVolume, SynthConstants.MinVolume)
    }

    /**
     * Loads the specified sound font.
     */
    public func loadSoundFont(_ data: Uint8Array) throws {
        let input: ByteBuffer = ByteBuffer.fromBuffer(data)
        let soundFont: Hydra = Hydra()
        try soundFont.load(input)
        let programs: Set<Double> = self._sequencer.instrumentPrograms
        let percussionKeys: Set<Double> = self._sequencer.percussionKeys
        try self._synth.loadPresets(soundFont, programs, percussionKeys, true)
    }

    /**
     * Loads the specified presets.
     */
    internal func loadPresets(_ presets: List<Preset>?) {
        self._synth.presets = presets
    }

    /**
     * Limits the time range for which the export is done.
     */
    public func limitExport(_ range: PlaybackRange) throws {
        self._sequencer.mainPlaybackRange = range
        try self._sequencer.mainSeek(self._sequencer.mainTickPositionToTimePosition(range.startTick))
    }

    /**
     * Sets the transposition pitch of a given channel. This pitch is additionally applied beside the
     * ones applied already via .
     */
    public func setChannelTranspositionPitch(_ channel: Double, _ semitones: Double) throws {
        try self._synth.setChannelTranspositionPitch(channel, semitones)
    }

    /**
     * Applies the given transposition pitches used for general pitch changes that should be applied to the song.
     * Used for general transpositions applied to the file.
     */
    public func applyTranspositionPitches(_ mainTranspositionPitches: Map<Double, Double>) throws {
        try self._synth.applyTranspositionPitches(mainTranspositionPitches)
    }

    /**
     * Loads the given midi file for synthesis.
     */
    public func loadMidiFile(_ midi: MidiFile) throws {
        try self._sequencer.loadMidi(midi)
    }

    /**
     * Updates the sync points used for time synchronization with a backing track.
     */
    public func updateSyncPoints(_ syncPoints: List<BackingTrackSyncPoint>) {
        self._sequencer.mainUpdateSyncPoints(syncPoints)
    }

    /**
     * Sets the current and initial volume of the given channel.
     */
    public func channelSetMixVolume(_ channel: Double, _ volume: Double) {
        var paramvolume = volume
        paramvolume = Math.max(paramvolume, SynthConstants.MinVolume)
        self._synth.channelSetMixVolume(channel, paramvolume)
    }

    private var _generatedAudioCurrentTime: Double = 0.0

    private var _generatedAudioEndTime: Double = 0.0

    public func setup() {
        self._synth.setupMetronomeChannel(self._sequencer.metronomeChannel, self._synth.metronomeVolume)
        let syncPoints: List<BackingTrackSyncPoint> = self._sequencer.currentSyncPoints
        let alphaTabEndTime: Double = self._sequencer.currentEndTime
        if syncPoints.length == 0.0 {
            self._generatedAudioEndTime = alphaTabEndTime
        } else {
            let lastSyncPoint: BackingTrackSyncPoint = syncPoints[(syncPoints.length - 1.0).toInt()]
            var endTime: Double = lastSyncPoint.syncTime
            let remainingTicks: Double = self._sequencer.currentEndTick - lastSyncPoint.synthTick
            if remainingTicks > 0 {
                endTime += MidiUtils.ticksToMillis(remainingTicks, lastSyncPoint.syncBpm)
            }
            self._generatedAudioEndTime = endTime
        }
    }

    /**
     * Renders the next chunk of audio and provides it as result.
     */
    public func render(_ milliseconds: Double) throws -> AudioExportChunk? {
        if self._sequencer.isFinished {
            return nil
        }
        let oneMicroBufferMillis: Double = (SynthConstants.MicroBufferSize * 1000.0) / self._synth.outSampleRate
        let microBufferCount: Double = Math.ceil(milliseconds / oneMicroBufferMillis)
        var samples: Float32Array = Float32Array(SynthConstants.MicroBufferSize * microBufferCount * SynthConstants.AudioChannels)
        let syncPoints: List<BackingTrackSyncPoint> = self._sequencer.currentSyncPoints
        var bufferPos: Double = 0.0
        var subBufferTime: Double = self._generatedAudioCurrentTime
        do {
            var i: Double = 0.0
            while i < microBufferCount {
                if syncPoints.length > 0 {
                    self._sequencer.currentUpdateSyncPoints(subBufferTime)
                    self._sequencer.currentUpdateCurrentTempo(self._sequencer.currentTime)
                    let newSpeed: Double = self._sequencer.syncPointTempo / self._sequencer.currentTempo
                    if self._sequencer.playbackSpeed != newSpeed {
                        self._sequencer.playbackSpeed = newSpeed
                    }
                }
                self._sequencer.fillMidiEventQueue()
                try self._synth.synthesize(samples, bufferPos, SynthConstants.MicroBufferSize)
                bufferPos += SynthConstants.MicroBufferSize * SynthConstants.AudioChannels
                subBufferTime += oneMicroBufferMillis
                if self._sequencer.isFinished {
                    break
                }
                i += 1
            }
        }
        if bufferPos < samples.length {
            samples = samples.subarray(0.0, bufferPos)
        }
        let chunk: AudioExportChunk = AudioExportChunk()
        chunk.currentTime = self._generatedAudioCurrentTime
        chunk.endTime = self._generatedAudioEndTime
        chunk.currentTick = self._sequencer.currentTimePositionToTickPosition(self._sequencer.currentTime)
        chunk.endTick = self._sequencer.currentEndTick
        self._generatedAudioCurrentTime += milliseconds
        chunk.samples = samples
        if self._sequencer.isFinished {
            try self._synth.noteOffAll(true)
        }
        return chunk
    }
}
